import json
import re
from typing import Dict, List, Tuple

HEADER_RE = re.compile(r"^\[(?P<id>[^\]]+)\]$")
CHOICE_RE = re.compile(r"^\d+\.\s*(?P<text>.+?)\s*(?:->\s*(?P<target>\w[\w-]*))?$")
LINE_RE = re.compile(r"^(?P<speaker>[^:]+):\s*(?P<rest>.+)$")


def _split_sections(text: str) -> List[Tuple[str, List[str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        header = HEADER_RE.match(line)
        if header:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = header.group("id").strip()
            current_lines = []
        else:
            if current_id is None:
                continue
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    return sections


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections = _split_sections(text)

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_index: Dict[str, int] = {}

    def add_node(node_id: str, text_val: str, speaker: str, node_type: str) -> None:
        if node_id in node_index:
            return
        node_index[node_id] = len(nodes)
        nodes.append(
            {
                "id": node_id,
                "text": text_val,
                "speaker": speaker,
                "type": node_type,
            }
        )

    for section_id, lines in sections:
        first_line = next((ln for ln in lines if ln.strip()), "")
        is_choice = bool(re.match(r"^\d+\.", first_line))

        if is_choice:
            add_node(section_id, "", "", "choice")
            for line in lines:
                choice_match = CHOICE_RE.match(line)
                if not choice_match:
                    continue
                choice_text = choice_match.group("text").strip()
                target = choice_match.group("target")
                if target:
                    edges.append({"from": section_id, "to": target, "text": choice_text})
        else:
            speaker = ""
            text_val = ""
            target = None
            if first_line:
                line_match = LINE_RE.match(first_line)
                if line_match:
                    speaker = line_match.group("speaker").strip()
                    rest = line_match.group("rest").strip()
                    if "->" in rest:
                        text_part, target_part = rest.rsplit("->", 1)
                        text_val = text_part.strip()
                        target = target_part.strip()
                    else:
                        text_val = rest
                else:
                    if "->" in first_line:
                        text_part, target_part = first_line.rsplit("->", 1)
                        text_val = text_part.strip()
                        target = target_part.strip()
                    else:
                        text_val = first_line.strip()

            add_node(section_id, text_val, speaker, "line")
            if target:
                edges.append({"from": section_id, "to": target, "text": ""})

    # Add placeholder nodes for missing targets
    for edge in list(edges):
        target = edge["to"]
        if target not in node_index:
            add_node(target, "", "", "line")

    # Enforce reachability from the first node
    if nodes:
        start_id = nodes[0]["id"]
        adjacency: Dict[str, List[str]] = {}
        for edge in edges:
            adjacency.setdefault(edge["from"], []).append(edge["to"])

        reachable = set()
        stack = [start_id]
        while stack:
            node_id = stack.pop()
            if node_id in reachable:
                continue
            reachable.add(node_id)
            for nxt in adjacency.get(node_id, []):
                if nxt not in reachable:
                    stack.append(nxt)

        if len(reachable) != len(nodes):
            nodes = [n for n in nodes if n["id"] in reachable]
            node_index = {n["id"]: idx for idx, n in enumerate(nodes)}
            edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": nodes, "edges": edges}


def _escape_dot_label(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"')


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]
    for node in graph["nodes"]:
        node_id = node["id"]
        node_type = node.get("type", "")
        label = node_id
        shape = "box" if node_type == "line" else "diamond"
        lines.append(f"  \"{_escape_dot_label(node_id)}\" [label=\"{_escape_dot_label(label)}\", shape={shape}];")
    for edge in graph["edges"]:
        src = edge["from"]
        dst = edge["to"]
        text = edge.get("text", "")
        if text:
            lines.append(
                f"  \"{_escape_dot_label(src)}\" -> \"{_escape_dot_label(dst)}\" [label=\"{_escape_dot_label(text)}\"];"
            )
        else:
            lines.append(
                f"  \"{_escape_dot_label(src)}\" -> \"{_escape_dot_label(dst)}\";"
            )
    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
        f.write("\n")

    dot = graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
        f.write("\n")


if __name__ == "__main__":
    main()
